<?php
require_once __DIR__.'/_common.php';
$total=sponsor_count($conn,"SELECT COUNT(*) total FROM users u JOIN roles r ON r.id=u.role_id WHERE r.slug='candidate'");
$active=sponsor_count($conn,"SELECT COUNT(*) total FROM users u JOIN roles r ON r.id=u.role_id WHERE r.slug='candidate' AND u.status='active'");
$rows=sponsor_rows($conn,"SELECT u.id,u.first_name,u.last_name,u.province,u.qualification_level,u.employment_status,u.status,u.created_at,cp.professional_title,cp.completion_percent FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN candidate_profiles cp ON cp.user_id=u.id WHERE r.slug='candidate' ORDER BY u.created_at DESC LIMIT 500");
sponsor_header('Participant overview','participants','A privacy-conscious view of candidate accounts; account status is not proof of programme enrolment.'); ?>
<section class="sp-stats"><article class="sp-stat"><div class="sp-stat-top">Candidate accounts <span class="sp-glyph">♙</span></div><strong><?= number_format($total) ?></strong><small>All candidate role accounts</small></article><article class="sp-stat"><div class="sp-stat-top">Active accounts <span class="sp-glyph">✓</span></div><strong><?= number_format($active) ?></strong><small>Account status marked active</small></article><article class="sp-stat"><div class="sp-stat-top">Other account statuses <span class="sp-glyph">◷</span></div><strong><?= number_format(max(0,$total-$active)) ?></strong><small>Pending, suspended or disabled</small></article></section>
<div class="sp-card"><div class="sp-toolbar"><input class="sp-search" data-search="#participantTable" placeholder="Search name, title, province or status…" aria-label="Search participants"><span class="sp-muted">Showing up to 500 most recently created accounts</span><a class="sp-btn" href="<?= url('sponsor/export.php?dataset=participants') ?>">↓ Export CSV</a></div><div class="sp-tablewrap"><table id="participantTable"><thead><tr><th>Candidate</th><th>Professional title</th><th>Province</th><th>Qualification</th><th>Employment status</th><th>Profile completion</th><th>Account status</th><th>Created</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= sponsor_e(trim($r['first_name'].' '.$r['last_name'])) ?></strong></td><td><?= sponsor_e($r['professional_title']?:'—') ?></td><td><?= sponsor_e($r['province']?:'—') ?></td><td><?= sponsor_e($r['qualification_level']?sponsor_status((string)$r['qualification_level']):'—') ?></td><td><?= sponsor_e($r['employment_status']?sponsor_status((string)$r['employment_status']):'—') ?></td><td><?= $r['completion_percent']===null?'—':(int)$r['completion_percent'].'%' ?></td><td><span class="sp-pill <?= sponsor_e($r['status']) ?>"><?= sponsor_e(sponsor_status((string)$r['status'])) ?></span></td><td><?= sponsor_e(sponsor_date($r['created_at'])) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="8" class="sp-empty">No candidate accounts found.</td></tr><?php endif; ?></tbody></table></div></div><div class="sp-note" style="margin-top:15px">Privacy notice: this view excludes email addresses, phone numbers, dates of birth and other direct contact details. It provides a limited operational summary for sponsor oversight.</div><?php sponsor_footer(); ?>
